  function inspector() { return `<aside class="inspector"><section class="inspect-section"><h3>会话详情</h3>${[['提供方','DeepSeek'],['模式','Workspace write'],['工作目录','./codekanban'],['工作树','main'],['开始时间','10:24 AM']].map(([a,b])=>`<div class="inspect-row"><span>${a}</span><span>${b}</span></div>`).join('')}</section><section class="inspect-section"><h3>上下文窗口</h3><div class="row small" style="justify-content:space-between;margin-bottom:10px"><span>34% 已使用</span><span class="subtle">44k / 128k</span></div><div class="progress"><span></span></div><p class="small subtle" style="font-size:10px;margin-top:10px">保留空间，让下一步更从容。</p></section><section class="inspect-section"><div class="row"><h3>代码变更</h3><span class="grow"></span><span class="small subtle">3 个文件</span></div>${['themes/core.ts','themes/builtin.json','styles/appearance.css'].map((f,i)=>`<a href="changes.html" class="changed-file">${icon('file')}<span>${f}</span><span class="diff-add">+${[84,36,52][i]}</span></a>`).join('')}<a href="changes.html" class="small" style="color:var(--accent);display:block;margin-top:14px">查看全部变更 →</a></section><section class="inspect-section"><h3>工作区工具</h3><div class="inspector-actions">${btn('技能','skills','layers')}${btn('审批','approval-history','shield')}${btn('记事本','notepad','note')}${btn('历史','history','clock')}</div></section></aside>`; }
  function workspacePage() { const selected = Number(new URLSearchParams(location.search).get('session')||0); return `<section class="work-center" data-region="main">${workTabs()}<header class="conversation-title"><div class="grow"><h2>${sessions[selected]||sessions[0]}</h2><div class="small subtle" style="font-size:10px;margin-top:5px">DeepSeek · main · 本地工作区</div></div>${badge('进行中','accent')}${ib('定时发送','schedule','clock')}${ib('查看会话树','session-tree','more')}</header><div class="conversation-body"><div class="conversation-inner"><div class="message-user">帮我扩展主题机制，让界面既能自由定制，也能保持一致。先梳理现有组件，再提出一个可扩展的方案。</div><div class="message-meta">你 · 10:24 ${btn('编辑','message-edit',null,'quiet small')}</div><div class="assistant-label"><span class="assistant-symbol">✳</span> DeepSeek <span class="small subtle" style="font-weight:400">10:24</span></div><div class="assistant-message"><details class="tool-call"><summary>${icon('check')}已梳理现有主题结构 <span class="grow"></span><span class="subtle">8 秒</span>${icon('down')}</summary><pre>示例过程摘要：现有颜色由语义调色板统一生成，工作区由会话、终端、文件和 Git 面板组成。可以在保留业务逻辑的前提下增加布局令牌与扩展插槽。</pre></details><p>我会把主题从「一组颜色」扩展为完整的界面定义。业务组件仍然共用，设计语言可以自由变化。</p><div class="plan-list"><div class="plan-item done">${icon('check')}梳理页面、工作区与弹窗覆盖范围</div><div class="plan-item done">${icon('check')}定义语义颜色与布局令牌</div><div class="plan-item current">${icon('clock')}接入三套新界面与原版兼容层</div><div class="plan-item muted">${icon('grid')}验证响应式布局和主题导入</div></div><details class="tool-call"><summary>${icon('folder')}读取 <span class="mono">ui/src/themes/core.ts</span><span class="grow"></span><span class="subtle">完成</span>${icon('down')}</summary><pre>ThemeManifest → validate → resolve → apply\nlight / dark · layout · extension slots</pre></details><p>已经分离了 <strong>语义令牌、界面布局和组件扩展</strong>。这意味着修改圆角或阅读宽度不需要复制会话页面。</p><a href="changes.html" class="inline-change">${icon('branch')}<strong>查看本轮变更</strong><span class="grow"></span><span class="diff-add">+172</span><span class="diff-del">−18</span><span class="subtle">3 个文件</span>${icon('chevron')}</a><div class="row small subtle" style="margin-top:17px;gap:6px"><span class="dot" style="color:var(--accent)"></span> 正在准备下一步… <span class="grow"></span>${btn('执行详情','command',null,'quiet small')}</div></div></div></div><div class="composer-area"><form class="composer" id="composer-form"><div class="context-ribbon"><span class="eyebrow">CONTEXT</span><button type="button" data-action="context-file">@ 文件</button><button type="button" data-action="context-session"># 会话</button><button type="button" data-action="context-command">/ 命令</button></div><textarea id="composer-input" aria-label="发送消息" placeholder="继续描述你的想法，/ 命令，@ 文件或会话"></textarea><div class="composer-bottom">${ib('添加附件','attachment','plus')}<select aria-label="权限模式"><option>Workspace write</option><option>Read only</option></select><span class="grow"></span><select aria-label="模型"><option>DeepSeek · High</option><option>Claude Code</option><option>OpenCode</option><option>Pi</option></select>${ib('打开技能目录','skills','layers')}<button class="primary icon-button" type="submit" aria-label="发送消息">${icon('send')}</button></div></form><div class="composer-hint">Enter 换行 · ⌘ / Ctrl + Enter 发送 · 静态消息不会发送给模型</div></div></section>`+sessionSidebar(); }
  function terminalPage() { return `<section class="work-center" data-region="main">${workTabs()}<div class="conversation-title"><h2>终端工作区</h2><span class="pill mono">zsh · main</span><span class="grow"></span>${btn('历史会话','history','clock','quiet small')}${btn('新终端','terminal-new','plus','small')}</div><div class="terminal"><pre id="terminal-output"><span class="subtle"># 以下内容为演示输出，不会执行真实 shell 命令。</span>\n\n<span class="prompt">➜  codekanban</span> <span class="muted">git</span> status\nOn branch main\nYour branch is up to date with 'origin/main'.\n\nChanges not staged for commit:\n  <span class="success-text">modified:   ui/src/themes/core.ts\n  modified:   ui/src/themes/builtin.json\n  modified:   ui/src/styles/appearance.css</span>\n\n<span class="prompt">➜  codekanban</span> pnpm test\n\n<span class="success-text"> ✓ theme validation\n ✓ theme inheritance\n ✓ appearance persistence\n ✓ legacy color compatibility</span>\n\n<span class="subtle"> Demo output · 4 checks shown · no real test process</span>\n</pre><form id="terminal-form" class="terminal-command"><span class="prompt">➜ codekanban</span><input id="terminal-input" aria-label="演示终端命令" placeholder="输入 help 查看演示命令" autocomplete="off" spellcheck="false"></form></div><div class="terminal-footer"><span>zsh</span><span>80 × 24</span><span>UTF-8</span><span class="grow"></span>${btn('清空','terminal-clear',null,'quiet small')}${btn('字体与配色','open-settings',null,'quiet small')}</div></section>`+sessionSidebar(); }
  const code = ["import { computed } from 'vue';",'',"import { resolveTheme } from './core';", "import { useAppearanceStore } from '@/stores/appearance';",'', '/** One workspace. More ways to make it yours. */', 'export function useInterfaceTheme() {', '  const appearance = useAppearanceStore();', '', '  const theme = computed(() =>', '    resolveTheme(', '      appearance.themeId,', '      appearance.themes,', '      appearance.scheme,', '      appearance.overrides,', '    ),', '  );', '', '  return { theme };', '}', '', '// UI prototype fixture — not the production source.'];
